var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('parses long strings that the original would reject', function () {
    var str = '1' + '0'.repeat(94) + ' days'; // length 100: original returns undefined
    assert.strictEqual(str.length, 100);
    assert.strictEqual(ms(str), undefined);
    var str2 = '1' + '0'.repeat(95) + ' days'; // length 101
    assert.strictEqual(str2.length, 101);
    assert.strictEqual(ms(str2), 100 * 86400000);
  });
});

